ValidationRule.errorConditionFormula:
AND(
    /* Bypass check */
    NOT(
        AND(
            EYI_IsAutomationBypassed__c = TRUE,
            EYI_AutomationBypassDatetime__c = NOW()
        )
    ),

    /* Stage transition restriction */
    ISPICKVAL(Stages__c , "Eligible To Raise Invoice"),
    NOT(ISPICKVAL(PRIORVALUE(Stages__c), "Invoice Received"))
)
